const{chromium}=require('playwright'),fs=require('fs');const out={cases:[],errors:[]};
(async()=>{const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:390,height:844},serviceWorkers:'allow'});const p=await c.newPage();
try{await p.goto('https://louisriv26.github.io/App-Test/?e12='+Date.now(),{waitUntil:'domcontentloaded',timeout:120000});await p.waitForFunction(()=>getComputedStyle(document.getElementById('loading')).display==='none',null,{timeout:120000});await p.evaluate(()=>{const o=document.getElementById('onboarding-overlay');if(o&&getComputedStyle(o).display!=='none')finishOnboarding()});
await p.evaluate(async()=>{await goSearch();await setSupplementMode('aflp',{persist:false,rerender:false,silent:true,origin:'qa'});});
const btn=p.locator('#screen-search .documentary-view-status.show .documentary-view-status-btn').filter({hasText:'Changer'});await btn.focus();const before=await p.evaluate(()=>({id:document.activeElement.id,txt:document.activeElement.textContent.trim(),cls:document.activeElement.className}));await p.keyboard.press('Enter');await p.waitForFunction(()=>document.getElementById('documentary-view-overlay').classList.contains('show'));await p.keyboard.press('Escape');await p.waitForTimeout(100);const afterEsc=await p.evaluate(()=>({tag:document.activeElement.tagName,id:document.activeElement.id,txt:document.activeElement.textContent.trim(),cls:document.activeElement.className}));out.cases.push({case:'search_visible_change_escape',before,afterEsc,pass:afterEsc.txt==='Changer'});
await btn.focus();await p.keyboard.press('Enter');await p.waitForFunction(()=>document.getElementById('documentary-view-overlay').classList.contains('show'));const normal=p.locator('#documentary-view-overlay [data-documentary-choice="enriched"]');await normal.focus();await p.keyboard.press('Enter');await p.waitForTimeout(500);const afterChoice=await p.evaluate(()=>({tag:document.activeElement.tagName,id:document.activeElement.id,txt:document.activeElement.textContent.trim(),cls:document.activeElement.className,mode:supplementMode,statusShown:document.querySelector('#screen-search .documentary-view-status')?.classList.contains('show')}));out.cases.push({case:'search_change_to_normal',afterChoice,pass:afterChoice.mode==='enriched'&&afterChoice.tag!=='BODY'});
}catch(e){out.errors.push(String(e&&e.stack||e))}finally{await c.close();await b.close()}out.overall=out.errors.length?'HARNESS_ERROR':(out.cases.every(x=>x.pass)?'PASS':'FAIL');fs.writeFileSync('e12-targeted.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));if(out.overall!=='PASS')process.exitCode=1})();